function sweptHit(fromX, fromY, toX, toY, brick, r) {
  const L = brick.x - r, R = brick.x + brick.w + r;
  const T = brick.y - r, B = brick.y + brick.h + r;
  const dx = toX - fromX, dy = toY - fromY;

  const scaleX = (v) => dx !== 0 ? v / dx : Infinity;

  // entry times to enter/exit each slab
  const tEnterX = dx !== 0 ? Math.min((L - fromX) / dx, (R - fromX) / dx) : -Infinity;
  const tExitX  = dx !== 0 ? Math.max((L - fromX) / dx, (R - fromX) / dx) : Infinity;
