      ball.x = fromX + (ball.x - fromX) * path.t;
      ball.y = fromY + (ball.y - fromY) * path.t;
      if (path.face === 'x') faceX = true;
      else if (path.face === 'y') faceY = true;
      else { faceX = faceY = true; } // corner
