// --- Brick bounce (pure) ---------------------------------------------------

// Number of sub-steps used by the sweep, only for the discrete high-speed
// look-ahead. Kept small so a frame stays cheap.
const SWEEP_STEPS = 8;

// True if the swept segment (fromX,fromY)->(toX,toY) crosses the local / global
// region of the brick AND the ball is (or will be) overlapping this frame.
// Returns the entry time `t` and the face(s) entered ('x' | 'y' | 'both'), or
// null when there is no hit this frame.
//
// The test runs against the brick expanded by the ball radius (so the circle
// becomes a moving point) and uses the slab (Cyrus–Beck) method: the axis whose
// slab becomes active LAST is the face that was actually hit.
function sweptHit(fromX, fromY, toX, toY, brick, r) {
  const L = brick.x - r, R = brick.x + brick.w + r;
  const T = brick.y - r, B = brick.y + brick.h + r;
  const dx = toX - fromX, dy = toY - fromY;

  const tinX = dx === 0 ? -Infinity : Math.min((L - fromX) / dx, (R - fromX) / dx);
  const toutX = dx === 0 ? Infinity : Math.max((L - fromX) / dx, (R - fromX) / dx);
  const tinY = dy === 0 ? -Infinity : Math.min((T - fromY) / dy, (B - fromY) / dy);
  const toutY = dy === 0 ? Infinity : Math.max((T - fromY) / dy, (B - fromY) / dy);

  const tin = Math.max(tinX, tinY);
  const tout = Math.min(toutX, toutY);

  // No part of this frame's movement sits inside the expanded box.
  if (tin > tout || tout < 0 || tin > 1) return null;

  let face;
  if (tinX === tinY) face = 'both';
  else if (tinX > tinY) face = 'x';
  else face = 'y';

  return { t: Math.max(tin, 0), face };
}

// The ball is already overlapping the (unexpanded) brick: resolve by pushing it
// out through the face with the SMALLEST penetration and flips that component.
// Equal penetration = a corner / diagonal hit -> flip both.
function resolveOverlap(ball, brick) {
  const penX = Math.min(
    ball.x + ball.r - brick.x,
    brick.x + brick.w - (ball.x - ball.r),
  );
  const penY = Math.min(
    ball.y + ball.r - brick.y,
    brick.y + brick.h - (ball.y - ball.r),
  );

  let flipX = false, flipY = false;

  if (penX < penY) {
    flipX = true;
    ball.x = ball.x < brick.x ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (penY < penX) {
    flipY = true;
    ball.y = ball.y < brick.y ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    flipX = flipY = true;
    if (ball.x < brick.x) ball.x = brick.x - ball.r;
    else if (ball.x > brick.x + brick.w) ball.x = brick.x + brick.w + ball.r;
    if (ball.y < brick.y) ball.y = brick.y - ball.r;
    else if (ball.y > brick.y + brick.h) ball.y = brick.y + brick.h + ball.r;
  }

  return { flipX, flipY };
}

// Heads-up bounce: the ball crossed the brick but is no longer touching it
// this frame (fast ball tunnelling over the brick). Re-enter at the swept
// contact point (tangent to the brick -> no sticky re-overlap) and flip the
// axis that was crossed.
function resolveTunnel(ball, brick, path) {
  const fromX = ball.px ?? ball.x, fromY = ball.py ?? ball.y;
  ball.x = fromX + (ball.x - fromX) * path.t;
  ball.y = fromY + (ball.y - fromY) * path.t;
  return { flipX: path.face !== 'y', flipY: path.face !== 'x' };
}

// Pure brick collision resolver: given the ball and the brick grid, applies a
// real bounce to the ball (face-accurate, push-out, seam-safe, tunnel-safe) and
// returns the list of bricks that were hit (the caller marks them dead + scores
// them). A ball crossing a seam overlaps two bricks in the SAME pass, so every
// flip is applied AT MOST ONCE per axis, otherwise `vy = -vy` applied twice
// would cancel out and the ball would plough straight through.
export function bounceBricks(ball, bricks) {
  const hit = [];
  let flipX = false, flipY = false;

  const fromX = ball.px ?? ball.x, fromY = ball.py ?? ball.y;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    const touching = collides(ball, brick);
    const path = sweptHit(fromX, fromY, ball.x, ball.y, brick, ball.r);

    if (!touching && path === null) continue;

    const res = touching ? resolveOverlap(ball, brick) : resolveTunnel(ball, brick, path);
    if (res.flipX) flipX = true;
    if (res.flipY) flipY = true;
    hit.push(brick);
  }

  // Apply each axis flip at most once across the whole pass (#1 neighbours).
  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  return hit;
}

// --- Rendering (DOM): brick collision logic STILL mixed in here ------------

// Main render loop. Brick collision happens first (via `bounceBricks`), then
// the surviving bricks are drawn. Resolution is pure; only the scoring stays
// entangled with the render loop for now (debt #2).
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Resolve the bounce FIRST (pure, testable), then score the broken bricks.
  const hit = bounceBricks(state.ball, state.bricks);
  for (const brick of hit) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // Bricks: draw the survivors.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

