edits.newText:
// --- issue #1: brick bounce -------------------------------------------------

// Helpers to build a minimal brick and a ball with an explicit previous position.
function brick(x = 100, y = 200, w = 72, h = 20) {
  return { x, y, w, h, alive: true, row: 0, points: 10 };
}

function ballAt(x, y, vx, vy, px = x, py = y) {
  return { x, y, r: 7, vx, vy, px, py };
}

test('#1 bounce: head-on top hit flips vy only', () => {
  const b = brick();
  // Ball climbs (vy < 0) into the bottom face of the brick.
  const ball = ballAt(130, 216, 0, -500, 130, 240);
  const hit = bounceBricks(ball, [b]);
  assert.deepEqual(hit, [b]);
  assert.ok(ball.vy > 0, 'should bounce back downward: ' + ball.vy);
  assert.equal(ball.vx, 0, 'horizontal component must be left unchanged');
});

test('#1 bounce: side hit flips vx only', () => {
  const b = brick();
  // Ball drives sideways into the right face of the brick from outside.
  const ball = ballAt(283, 310, -500, 0, 292, 310);
  const hit = bounceBricks(ball, [b]);
  assert.deepEqual(hit, [b]);
  assert.ok(ball.vx > 0, 'should bounce back to the right: ' + ball.vx);
  assert.equal(ball.vy, 0, 'vertical component must be left unchanged');
});

test('#1 bounce: corner hit flips both components', () => {
  const b = brick();
  // Equal penetration on both axes => diagonal hit.
  const ball = ballAt(92, 206, -400, -400, 112, 224);
  const hit = bounceBricks(ball, [b]);
  assert.deepEqual(hit, [b]);
  assert.ok(ball.vx > 0 && ball.vy > 0, 'both components should flip');
});

test('#1 push-out: ball no longer overlaps any surviving brick', () => {
  const b = brick();
  const ball = ballAt(130, 216, 0, -500, 130, 240);
  bounceBricks(ball, [b]);
  assert.equal(collides(ball, b), false, 'ball must be pushed outside the brick');
});

test('#1 neighbours: two bricks sharing a face flip vy exactly once', () => {
  // Two overlapping bricks (a duplicated seam): each one detects the SAME top
  // hit. Applying `vy = -vy` twice would cancel out and let the ball through.
  const b1 = brick();
  const b2 = brick(); // identical geometry => both want the same flip
  const vx = 0, vy = -500;
  const ball = ballAt(136, 216, vx, vy, 136, 240);
  const hit = bounceBricks(ball, [b1, b2]);
  assert.deepEqual(sortedHit(hit), [b1, b2]);
  assert.equal(ball.vy, -vy, 'vy must flip exactly once (not cancel out)');
  assert.equal(ball.vx, vx);
  function sortedHit(arr) {
    return [...arr].sort((a, b2) => (a === b2 ? 0 : -1));
  }
});

test('#1 tunnelling: fast ball that jumps over a brick still bounces', () => {
  // Brick spans y 200..220; expanded by the radius: 193..227. The ball moves
  // from y=160 to y=240 in one frame, so no discrete sample ever overlaps.
  const b = brick();
  const ball = ballAt(236, 240, 0, -700, 236, 160); // px above, cur below
  const hit = bounceBricks(ball, [b]);
  assert.deepEqual(hit, [b]);
  assert.ok(ball.vy > 0, 'must bounce off even though it tunneled over');
  assert.equal(collides(ball, b), false, 'ball must not be left inside the brick');
});

test('#1 no hit: ball passing clear of a brick bounces nothing', () => {
  const b = brick();
  const ball = ballAt(0, 400, 200, 0, 0, 400);
  const hit = bounceBricks(ball, [b]);
  assert.deepEqual(hit, []);
  assert.equal(ball.vx, 200);
  assert.equal(ball.vy, 0);
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

